// Climate regions and radiation, in generated worlds (hand-made maps are mild and clean).
//
//   regions    the north of the map runs cold, the south hot, the middle mild, with a
//              wandering border (a slow noise field). Cold: nights are cold from autumn,
//              and winter days too. Hot: no cold short of a blizzard, and summer days
//              dry you out twice as fast.
//   radiation  in a nuclear winter only: hot spots (the high points of another noise field,
//              well away from the start). Standing in one costs health and leaves a bad
//              thought; crates there hold twice the loot, which is why anyone goes in.
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Climate
{

    /// <summary>Kept clean around the start, so a new game isn't poisoned from the first step.</summary>
    public const int CLEAN_RADIUS = 40;

    public const int RAD_EVERY = 20;

    public const int RAD_DAMAGE = 2;

    public static string climateAt(SimState state, int x, int y)
    {
        var world = state.world;
        if (!Js.T(world))
        {
            return "mild";
        }
        var t = ((double)(y) / (world.size)) + (0.25 * (NatureMod.noise(world.seed, x, y, 64, 41) - 0.5));
        return (t < 0.33) ? "cold" : ((t > 0.67) ? "hot" : "mild");
    }
    public static string climateAt(SimState state, double x, double y) => climateAt(state, (int)x, (int)y);

    /// <summary>Is the open air cold here and now, by region and season? (Blizzards are handled by the caller.)</summary>
    public static bool regionCold(SimState state, int x, int y)
    {
        var climate = climateAt(state, x, y);
        var season = Seasons.seasonOf(state.tick);
        if (climate == "hot")
        {
            return false;
        }
        var night = Time.isNight(state.tick);
        if (climate == "cold")
        {
            return ((season == "winter") || (Js.T(night) && (season == "autumn"))) || (Js.T(night) && Js.T(state.settings.winter));
        }
        return Js.T(night) && ((season == "winter") || Js.T(state.settings.winter));
    }
    public static bool regionCold(SimState state, double x, double y) => regionCold(state, (int)x, (int)y);

    /// <summary>Summer days in the hot south: thirst comes twice as fast.</summary>
    public static bool scorching(SimState state, int x, int y)
    {
        return ((Seasons.seasonOf(state.tick) == "summer") && !Js.T(Time.isNight(state.tick))) && (climateAt(state, x, y) == "hot");
    }
    public static bool scorching(SimState state, double x, double y) => scorching(state, (int)x, (int)y);

    public static bool isRadioactive(SimState state, int x, int y)
    {
        var world = state.world;
        if (!Js.T(world) || !Js.T(state.settings.winter))
        {
            return false;
        }
        var c = ((double)(world.size) / (2));
        if (((JsMath.pow((x - c), 2)) + (JsMath.pow((y - c), 2))) < (CLEAN_RADIUS * CLEAN_RADIUS))
        {
            return false;
        }
        return NatureMod.noise(world.seed, x, y, 30, 42) > 0.8;
    }
    public static bool isRadioactive(SimState state, double x, double y) => isRadioactive(state, (int)x, (int)y);

    /// <summary>Every RAD_EVERY ticks in a hot spot: health, and the thought of it.</summary>
    public static void updateRadiation(SimState state, Survivor s)
    {
        if (((state.tick % RAD_EVERY) != 0) || !Js.T(isRadioactive(state, s.pos.x, s.pos.y)))
        {
            return;
        }
        s.health = JsMath.max(0, s.health - RAD_DAMAGE);
        s.lastHurtBy = "radiation";
        Mood.addThought(state, s, "irradiated");
    }
}
